/**
 * 负责 providers、agents、game、可选 audit 及已解析运行配置的类型结构。输入／输出关系分别描述模型 API、ACP 进程、玩家覆盖与装配结果。
 * 配置数据由读取／解析和 setup 所有者管理；此契约不加载文件或环境、不创建 Agent，也不拥有角色库存或全局缓存。
 */
/** `openai` 同时覆盖 OpenRouter 等 Chat Completions 兼容网关。 */
import type { Locale } from "@ai-werewolf-arena/game-contract";
export type ProviderType = "openai" | "anthropic" | "acp";
export type GameBoard = string;
export type ReasoningEffort = "none" | "minimal" | "low" | "medium" | "high" | "xhigh";

export interface LlmProviderConfig {
  type: "openai" | "anthropic";
  apiKey: string;
  baseURL?: string;
  userAgent?: string;
  maxConcurrentRequests?: number;
}

/** ACP 是 Agent 进程传输，不是模型 API Provider。 */
export interface AcpProviderConfig {
  type: "acp";
  transport: "stdio";
  command: string;
  args: string[];
  env: Record<string, string>;
  cwd?: string;
  initializeTimeoutMs?: number;
  maxConcurrentRequests?: number;
  sessionConfigOptions: Record<string, string | boolean>;
}

export type ProviderConfig = LlmProviderConfig | AcpProviderConfig;

export interface AgentPromptConfig {
  personalityPrompt?: string;
}

export interface AgentProfileConfig extends AgentPromptConfig {
  model: string;
  temperature?: number;
  maxTokens?: number;
  reasoningEffort?: ReasoningEffort;
  thinkingEnabled?: boolean;
}

export interface LlmAgentEntryConfig extends AgentProfileConfig {
  kind: "llm";
  provider: string;
}

export interface AcpAgentEntryConfig extends AgentPromptConfig {
  kind: "acp";
  provider: string;
  /** 静态启动参数；不得包含身份或对局状态。 */
  spawnArgs?: string[];
  sessionReuse?: "per_player";
  actionTransport?: "mcp";
}

export type AgentEntryConfig = LlmAgentEntryConfig | AcpAgentEntryConfig;

export interface ProvidersConfig {
  default: string;
  items: Record<string, ProviderConfig>;
}

export interface AgentsConfig {
  default: string;
  items: Record<string, AgentEntryConfig>;
}

/** 对局引用已定义的 Agent；对象形式可覆盖提示词及 ACP 启动参数。 */
export type GameAgentSelection =
  | string
  | {
      agent: string;
      spawnArgs?: string[];
      personalityPrompt?: string;
    };

export type LocalizedPrompt = string | Partial<Record<Locale, string>>;
export interface PlayerConfig {
  name?: string;
  agent?: string;
  spawnArgs?: string[];
  /** null 明确清除继承人格；字符串原文保留。 */
  personalityPrompt?: LocalizedPrompt | null;
}

export interface GameConfig {
  board?: GameBoard;
  maxDays?: number;
  maxRuntimeMs?: number;
  llmTimeoutMs?: number;
  trace?: boolean;
  printAllEvents?: boolean;
  printChat?: boolean;
  streamEvents?: boolean;
  color?: boolean;
  printLlmIo?: boolean;
  printThinking?: boolean;
  printPrivateEvents?: boolean;
  recordRootDir?: string;
  agent?: string;
  roleAgents?: Record<string, GameAgentSelection>;
  playerAgents?: Record<string, GameAgentSelection>;
  players?: Record<string, PlayerConfig>;
  locale?: Locale;
  displayLocale?: Locale;
  seed?: string;
}

export interface DebugSummaryAgentConfig {
  enabled?: boolean;
  agentName?: string;
  timeoutMs?: number;
  maxAttempts?: number;
  concurrency?: number;
  publicMaxItems?: number;
  maxItems?: number;
  playerMaxItems?: number;
}

export interface DebugSummaryConfig {
  agent?: DebugSummaryAgentConfig;
}

/** 唯一支持的运行时配置：providers、agents、一个具名 game 和可选 audit 配置。 */
export interface RuntimeConfig {
  providers: ProvidersConfig;
  agents: AgentsConfig;
  game: GameConfig;
  debugSummary?: DebugSummaryConfig;
}

export interface ResolvedAuditConfig {
  profile: ResolvedAgentRuntimeProfile;
  timeoutMs: number;
  maxAttempts: number;
  concurrency: number;
  publicMaxItems: number;
  maxItems: number;
  playerMaxItems: number;
}

export interface ResolvedAgentRuntimeProfile extends AgentPromptConfig {
  name: string;
  providerName: string;
  provider: ProviderConfig;
  kind: "llm" | "acp";
  model?: string;
  temperature?: number;
  maxTokens?: number;
  reasoningEffort?: ReasoningEffort;
  thinkingEnabled?: boolean;
  spawnArgs?: string[];
  sessionReuse?: "per_player";
  actionTransport?: "mcp";
}

/**
 * 负责 unknown 配置的字段校验、默认归一和环境值解析。输入为原配置及环境表，输出 providers／agents／game／audit 配置或原字段错误。
 * 本解析模块不读文件、不启动 Agent 或写全局配置，实际执行及资源仍由运行装配持有。
 */
import type {
  AcpAgentEntryConfig,
  AgentEntryConfig,
  AgentsConfig,
  DebugSummaryConfig,
  GameAgentSelection,
  GameConfig,
  GameBoard,
  LlmAgentEntryConfig,
  ProviderConfig,
  ProvidersConfig,
  ReasoningEffort,
  RuntimeConfig,
  PlayerConfig,
  LocalizedPrompt,
} from "./contracts";
import { isLocale, type Locale } from "@ai-werewolf-arena/game-contract";

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function assertKnownKeys(value: Record<string, unknown>, keys: string[], field: string): void {
  const allowed = new Set(keys);
  for (const key of Object.keys(value)) {
    if (!allowed.has(key)) {
      throw new Error(`runtime_config_unknown_field: ${field}.${key}`);
    }
  }
}

function readRequiredString(value: unknown, field: string): string {
  if (typeof value !== "string" || !value.trim()) {
    throw new Error(`runtime_config_required_string_invalid: ${field}`);
  }
  return value.trim();
}

function readOptionalString(value: unknown, field: string): string | undefined {
  if (value === undefined) return undefined;
  return readRequiredString(value, field);
}

function readPromptText(value: unknown, field: string): string {
  readRequiredString(value, field);
  return value as string;
}

function readOptionalBoolean(value: unknown, field: string): boolean | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== "boolean") {
    throw new Error(`runtime_config_optional_boolean_invalid: ${field}`);
  }
  return value;
}

function readOptionalNumber(value: unknown, field: string): number | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== "number" || !Number.isFinite(value) || value < 0) {
    throw new Error(`runtime_config_optional_number_invalid: ${field}`);
  }
  return value;
}

function readOptionalPositiveInteger(value: unknown, field: string): number | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== "number" || !Number.isSafeInteger(value) || value <= 0) {
    throw new Error(`runtime_config_positive_integer_invalid: ${field}`);
  }
  return value;
}

function readOptionalMinimumInteger(
  value: unknown,
  field: string,
  minimum: number,
): number | undefined {
  const parsed = readOptionalPositiveInteger(value, field);
  if (parsed !== undefined && parsed < minimum) {
    throw new Error(`runtime_config_minimum_integer_invalid: ${field} >= ${minimum}`);
  }
  return parsed;
}

function readStringArray(value: unknown, field: string): string[] {
  if (value === undefined) return [];
  if (!Array.isArray(value) || value.some((item) => typeof item !== "string" || !item.trim())) {
    throw new Error(`runtime_config_string_array_invalid: ${field}`);
  }
  return value.map((item) => item.trim());
}

function resolveEnvironmentValue(
  value: string,
  field: string,
  environment: NodeJS.ProcessEnv,
): string {
  const match = /^\$\{([A-Z][A-Z0-9_]*)\}$/.exec(value.trim());
  if (!match) return value;
  const resolved = environment[match[1]]?.trim();
  if (!resolved) {
    throw new Error(`runtime_config_missing_environment_value: ${field} -> ${match[1]}`);
  }
  return resolved;
}

function readEnvironment(
  value: unknown,
  field: string,
  environment: NodeJS.ProcessEnv,
): Record<string, string> {
  if (value === undefined) return {};
  if (!isRecord(value)) {
    throw new Error(`runtime_config_environment_invalid: ${field}`);
  }
  return Object.fromEntries(
    Object.entries(value).map(([key, raw]) => [
      readRequiredString(key, `${field}.key`),
      resolveEnvironmentValue(
        readRequiredString(raw, `${field}.${key}`),
        `${field}.${key}`,
        environment,
      ),
    ]),
  );
}

function readSessionConfigOptions(value: unknown, field: string): Record<string, string | boolean> {
  if (value === undefined) return {};
  if (!isRecord(value)) {
    throw new Error(`runtime_config_acp_session_config_options_invalid: ${field}`);
  }
  return Object.fromEntries(
    Object.entries(value).map(([key, optionValue]) => {
      if (!key.trim() || (typeof optionValue !== "string" && typeof optionValue !== "boolean")) {
        throw new Error(`runtime_config_acp_session_config_option_invalid: ${field}.${key}`);
      }
      return [key, optionValue];
    }),
  );
}

function normalizeProviderConfig(
  name: string,
  raw: unknown,
  environment: NodeJS.ProcessEnv,
): ProviderConfig {
  if (!isRecord(raw)) {
    throw new Error(`runtime_config_provider_invalid: ${name}`);
  }
  const type = readRequiredString(raw.type, `providers.items.${name}.type`);
  if (type === "acp") {
    assertKnownKeys(
      raw,
      [
        "type",
        "transport",
        "command",
        "args",
        "env",
        "cwd",
        "initializeTimeoutMs",
        "sessionConfigOptions",
        "maxConcurrentRequests",
      ],
      `providers.items.${name}`,
    );
    const transport =
      raw.transport === undefined
        ? "stdio"
        : readRequiredString(raw.transport, `providers.items.${name}.transport`);
    if (transport !== "stdio") {
      throw new Error(`runtime_config_acp_transport_unsupported: ${name}`);
    }
    return {
      type: "acp",
      transport,
      command: readRequiredString(raw.command, `providers.items.${name}.command`),
      args: readStringArray(raw.args, `providers.items.${name}.args`),
      env: readEnvironment(raw.env, `providers.items.${name}.env`, environment),
      cwd: readOptionalString(raw.cwd, `providers.items.${name}.cwd`),
      initializeTimeoutMs: readOptionalPositiveInteger(
        raw.initializeTimeoutMs,
        `providers.items.${name}.initializeTimeoutMs`,
      ),
      maxConcurrentRequests: readOptionalPositiveInteger(
        raw.maxConcurrentRequests,
        `providers.items.${name}.maxConcurrentRequests`,
      ),
      sessionConfigOptions: readSessionConfigOptions(
        raw.sessionConfigOptions,
        `providers.items.${name}.sessionConfigOptions`,
      ),
    };
  }
  if (type !== "openai" && type !== "anthropic") {
    throw new Error(`runtime_config_provider_type_unsupported: ${name}`);
  }
  assertKnownKeys(
    raw,
    ["type", "apiKey", "baseURL", "userAgent", "maxConcurrentRequests"],
    `providers.items.${name}`,
  );
  return {
    type,
    apiKey: resolveEnvironmentValue(
      readRequiredString(raw.apiKey, `providers.items.${name}.apiKey`),
      `providers.items.${name}.apiKey`,
      environment,
    ),
    baseURL: readOptionalString(raw.baseURL, `providers.items.${name}.baseURL`),
    userAgent: readOptionalString(raw.userAgent, `providers.items.${name}.userAgent`),
    maxConcurrentRequests: readOptionalPositiveInteger(
      raw.maxConcurrentRequests,
      `providers.items.${name}.maxConcurrentRequests`,
    ),
  };
}

function normalizeProviders(raw: unknown, environment: NodeJS.ProcessEnv): ProvidersConfig {
  if (!isRecord(raw)) throw new Error("runtime_config_invalid_providers");
  assertKnownKeys(raw, ["default", "items"], "providers");
  if (!isRecord(raw.items)) throw new Error("runtime_config_invalid_providers_items");
  const items = Object.fromEntries(
    Object.entries(raw.items).map(([name, provider]) => [
      readRequiredString(name, "providers.items.key"),
      normalizeProviderConfig(name, provider, environment),
    ]),
  ) as Record<string, ProviderConfig>;
  if (Object.keys(items).length === 0) throw new Error("runtime_config_empty_providers_items");
  const defaultName = readRequiredString(raw.default, "providers.default");
  if (!items[defaultName])
    throw new Error(`runtime_config_provider_default_not_found: ${defaultName}`);
  return { default: defaultName, items };
}

function normalizeAgentProfile(raw: Record<string, unknown>, name: string): LlmAgentEntryConfig {
  assertKnownKeys(
    raw,
    [
      "kind",
      "provider",
      "model",
      "temperature",
      "maxTokens",
      "reasoningEffort",
      "thinkingEnabled",
      "personalityPrompt",
    ],
    `agents.items.${name}`,
  );
  const reasoningEffort =
    raw.reasoningEffort === undefined
      ? undefined
      : readRequiredString(raw.reasoningEffort, `agents.items.${name}.reasoningEffort`);
  if (
    reasoningEffort !== undefined &&
    !["none", "minimal", "low", "medium", "high", "xhigh"].includes(reasoningEffort)
  ) {
    throw new Error(`runtime_config_reasoning_effort_invalid: ${name}`);
  }
  return {
    kind: "llm",
    provider: readRequiredString(raw.provider, `agents.items.${name}.provider`),
    model: readRequiredString(raw.model, `agents.items.${name}.model`),
    temperature: readOptionalNumber(raw.temperature, `agents.items.${name}.temperature`),
    maxTokens: readOptionalPositiveInteger(raw.maxTokens, `agents.items.${name}.maxTokens`),
    reasoningEffort: reasoningEffort as ReasoningEffort | undefined,
    thinkingEnabled: readOptionalBoolean(
      raw.thinkingEnabled,
      `agents.items.${name}.thinkingEnabled`,
    ),
    personalityPrompt: readOptionalString(
      raw.personalityPrompt,
      `agents.items.${name}.personalityPrompt`,
    ),
  };
}

function normalizeAcpAgent(raw: Record<string, unknown>, name: string): AcpAgentEntryConfig {
  assertKnownKeys(
    raw,
    ["kind", "provider", "spawnArgs", "sessionReuse", "actionTransport", "personalityPrompt"],
    `agents.items.${name}`,
  );
  const sessionReuse =
    raw.sessionReuse === undefined
      ? undefined
      : readRequiredString(raw.sessionReuse, `agents.items.${name}.sessionReuse`);
  if (sessionReuse !== undefined && sessionReuse !== "per_player") {
    throw new Error(`runtime_config_acp_session_reuse_invalid: ${name}`);
  }
  const actionTransport =
    raw.actionTransport === undefined
      ? undefined
      : readRequiredString(raw.actionTransport, `agents.items.${name}.actionTransport`);
  if (actionTransport !== undefined && actionTransport !== "mcp") {
    throw new Error(`runtime_config_acp_action_transport_invalid: ${name}`);
  }
  return {
    kind: "acp",
    provider: readRequiredString(raw.provider, `agents.items.${name}.provider`),
    spawnArgs:
      raw.spawnArgs === undefined
        ? undefined
        : readStringArray(raw.spawnArgs, `agents.items.${name}.spawnArgs`),
    sessionReuse: sessionReuse as AcpAgentEntryConfig["sessionReuse"],
    actionTransport: actionTransport as AcpAgentEntryConfig["actionTransport"],
    personalityPrompt: readOptionalString(
      raw.personalityPrompt,
      `agents.items.${name}.personalityPrompt`,
    ),
  };
}

function normalizeAgents(raw: unknown, providers: ProvidersConfig): AgentsConfig {
  if (!isRecord(raw)) throw new Error("runtime_config_invalid_agents");
  assertKnownKeys(raw, ["default", "items"], "agents");
  if (!isRecord(raw.items)) throw new Error("runtime_config_invalid_agents_items");
  const items = Object.fromEntries(
    Object.entries(raw.items).map(([name, value]) => {
      if (!isRecord(value)) throw new Error(`runtime_config_agent_invalid: ${name}`);
      const kind = readRequiredString(value.kind, `agents.items.${name}.kind`);
      const agent =
        kind === "llm"
          ? normalizeAgentProfile(value, name)
          : kind === "acp"
            ? normalizeAcpAgent(value, name)
            : (() => {
                throw new Error(`runtime_config_agent_kind_unsupported: ${name}`);
              })();
      const provider = providers.items[agent.provider];
      if (!provider) {
        throw new Error(
          `runtime_config_agent_provider_not_found: agent=${name} provider=${agent.provider}`,
        );
      }
      if (agent.kind === "acp" && provider.type !== "acp") {
        throw new Error(`runtime_config_acp_agent_requires_acp_provider: ${name}`);
      }
      if (agent.kind === "llm" && provider.type === "acp") {
        throw new Error(`runtime_config_llm_agent_requires_llm_provider: ${name}`);
      }
      if (
        agent.kind === "llm" &&
        provider.type === "anthropic" &&
        agent.thinkingEnabled &&
        agent.temperature !== undefined
      ) {
        throw new Error(`runtime_config_anthropic_thinking_temperature_unsupported: ${name}`);
      }
      if (
        agent.kind === "llm" &&
        provider.type === "anthropic" &&
        agent.reasoningEffort &&
        !["low", "medium", "high"].includes(agent.reasoningEffort)
      ) {
        throw new Error(`runtime_config_anthropic_reasoning_effort_invalid: ${name}`);
      }
      return [readRequiredString(name, "agents.items.key"), agent];
    }),
  ) as Record<string, AgentEntryConfig>;
  if (Object.keys(items).length === 0) throw new Error("runtime_config_empty_agents_items");
  const defaultName = readRequiredString(raw.default, "agents.default");
  if (!items[defaultName])
    throw new Error(`runtime_config_agent_default_not_found: ${defaultName}`);
  return { default: defaultName, items };
}

function normalizeGameAgentSelection(
  value: unknown,
  field: string,
  agents: AgentsConfig,
): GameAgentSelection {
  if (typeof value === "string") {
    const agent = readRequiredString(value, field);
    if (!agents.items[agent]) throw new Error(`runtime_config_agent_not_found: ${agent}`);
    return agent;
  }
  if (!isRecord(value)) throw new Error(`runtime_config_agent_selection_invalid: ${field}`);
  assertKnownKeys(value, ["agent", "spawnArgs", "personalityPrompt"], field);
  const agent = readRequiredString(value.agent, `${field}.agent`);
  const profile = agents.items[agent];
  if (!profile) throw new Error(`runtime_config_agent_not_found: ${agent}`);
  const spawnArgs =
    value.spawnArgs === undefined
      ? undefined
      : readStringArray(value.spawnArgs, `${field}.spawnArgs`);
  if (spawnArgs && profile.kind !== "acp") {
    throw new Error(`runtime_config_spawn_args_require_acp_agent: ${field}`);
  }
  const personalityPrompt = readOptionalString(
    value.personalityPrompt,
    `${field}.personalityPrompt`,
  );
  return {
    agent,
    ...(spawnArgs ? { spawnArgs } : {}),
    ...(personalityPrompt !== undefined ? { personalityPrompt } : {}),
  };
}

function normalizeGameAgentSelections(
  value: unknown,
  field: string,
  agents: AgentsConfig,
): Record<string, GameAgentSelection> | undefined {
  if (value === undefined) return undefined;
  if (!isRecord(value)) throw new Error(`runtime_config_agent_selections_invalid: ${field}`);
  return Object.fromEntries(
    Object.entries(value).map(([key, selection]) => {
      if (key !== key.trim()) throw new Error(`runtime_config_selection_key_invalid: ${field}`);
      return [
        readRequiredString(key, `${field}.key`),
        normalizeGameAgentSelection(selection, `${field}.${key}`, agents),
      ];
    }),
  );
}

function normalizeGameConfig(raw: unknown, agents: AgentsConfig): GameConfig {
  if (!isRecord(raw)) throw new Error("runtime_config_invalid_game");
  assertKnownKeys(
    raw,
    [
      "board",
      "maxDays",
      "maxRuntimeMs",
      "llmTimeoutMs",
      "trace",
      "printAllEvents",
      "printChat",
      "streamEvents",
      "color",
      "printLlmIo",
      "printThinking",
      "printPrivateEvents",
      "recordRootDir",
      "agent",
      "roleAgents",
      "playerAgents",
      "players",
      "locale",
      "displayLocale",
      "seed",
    ],
    "game",
  );
  const board = raw.board === undefined ? undefined : readRequiredString(raw.board, "game.board");
  if (board !== undefined && !/^[a-z][a-z0-9_-]*$/.test(board)) {
    throw new Error(`runtime_config_board_invalid: ${board}`);
  }
  const agent =
    raw.agent === undefined
      ? undefined
      : normalizeGameAgentSelection(raw.agent, "game.agent", agents);
  if (agent !== undefined && typeof agent !== "string") {
    throw new Error("runtime_config_game_agent_must_be_name");
  }
  return {
    board: board as GameBoard | undefined,
    maxDays: readOptionalPositiveInteger(raw.maxDays, "game.maxDays"),
    maxRuntimeMs: readOptionalPositiveInteger(raw.maxRuntimeMs, "game.maxRuntimeMs"),
    llmTimeoutMs: readOptionalPositiveInteger(raw.llmTimeoutMs, "game.llmTimeoutMs"),
    trace: readOptionalBoolean(raw.trace, "game.trace"),
    printAllEvents: readOptionalBoolean(raw.printAllEvents, "game.printAllEvents"),
    printChat: readOptionalBoolean(raw.printChat, "game.printChat"),
    streamEvents: readOptionalBoolean(raw.streamEvents, "game.streamEvents"),
    color: readOptionalBoolean(raw.color, "game.color"),
    printLlmIo: readOptionalBoolean(raw.printLlmIo, "game.printLlmIo"),
    printThinking: readOptionalBoolean(raw.printThinking, "game.printThinking"),
    printPrivateEvents: readOptionalBoolean(raw.printPrivateEvents, "game.printPrivateEvents"),
    recordRootDir: readOptionalString(raw.recordRootDir, "game.recordRootDir"),
    agent,
    roleAgents: normalizeGameAgentSelections(raw.roleAgents, "game.roleAgents", agents),
    playerAgents: normalizeGameAgentSelections(raw.playerAgents, "game.playerAgents", agents),
    players: normalizePlayers(raw.players, agents),
    locale: readLocale(raw.locale, "game.locale"),
    displayLocale: readLocale(raw.displayLocale, "game.displayLocale"),
    seed: readOptionalString(raw.seed, "game.seed"),
  };
}

function readLocale(value: unknown, field: string): Locale | undefined {
  if (value === undefined) return undefined;
  if (!isLocale(value)) throw new Error(`runtime_config_locale_invalid: ${field}`);
  return value;
}

function normalizePlayers(
  value: unknown,
  agents: AgentsConfig,
): Record<string, PlayerConfig> | undefined {
  if (value === undefined) return undefined;
  if (!isRecord(value)) throw new Error("runtime_config_players_invalid");
  return Object.fromEntries(
    Object.entries(value).map(([seat, entry]) => {
      const field = `game.players.${seat}`;
      if (!isRecord(entry)) throw new Error(`runtime_config_player_invalid: ${field}`);
      assertKnownKeys(entry, ["name", "agent", "spawnArgs", "personalityPrompt"], field);
      let name: string | undefined;
      if (entry.name !== undefined) {
        if (typeof entry.name !== "string" || !entry.name.trim() || entry.name.length > 120)
          throw new Error(`runtime_config_player_name_invalid: ${field}.name`);
        name = entry.name; // 保留用户名字原文，不翻译或静默裁掉空白。
      }
      const agent = readOptionalString(entry.agent, `${field}.agent`);
      if (agent && !agents.items[agent])
        throw new Error(`runtime_config_agent_not_found: ${agent}`);
      const spawnArgs =
        entry.spawnArgs === undefined
          ? undefined
          : readStringArray(entry.spawnArgs, `${field}.spawnArgs`);
      if (spawnArgs && (!agent || agents.items[agent].kind !== "acp"))
        throw new Error(`runtime_config_spawn_args_require_explicit_acp_agent: ${field}`);
      let personalityPrompt: LocalizedPrompt | null | undefined;
      if (entry.personalityPrompt === null) personalityPrompt = null;
      else if (entry.personalityPrompt !== undefined) {
        if (typeof entry.personalityPrompt === "string")
          personalityPrompt = readPromptText(entry.personalityPrompt, `${field}.personalityPrompt`);
        else {
          if (!isRecord(entry.personalityPrompt))
            throw new Error(`runtime_config_prompt_invalid: ${field}`);
          assertKnownKeys(entry.personalityPrompt, ["zh-CN", "en"], `${field}.personalityPrompt`);
          if (!Object.keys(entry.personalityPrompt).length)
            throw new Error(`runtime_config_prompt_empty: ${field}`);
          personalityPrompt = Object.fromEntries(
            Object.entries(entry.personalityPrompt).map(([locale, text]) => [
              locale,
              readPromptText(text, `${field}.personalityPrompt.${locale}`),
            ]),
          );
        }
      }
      return [
        seat,
        {
          ...(name !== undefined ? { name } : {}),
          ...(agent ? { agent } : {}),
          ...(spawnArgs ? { spawnArgs } : {}),
          ...(personalityPrompt !== undefined ? { personalityPrompt } : {}),
        },
      ];
    }),
  );
}

function normalizeDebugSummaryConfig(raw: unknown, agents: AgentsConfig): DebugSummaryConfig {
  if (!isRecord(raw)) throw new Error("runtime_config_invalid_debug_summary");
  assertKnownKeys(raw, ["agent"], "debugSummary");
  if (raw.agent === undefined) return {};
  if (!isRecord(raw.agent)) throw new Error("runtime_config_invalid_debug_summary_agent");
  assertKnownKeys(
    raw.agent,
    [
      "enabled",
      "agentName",
      "timeoutMs",
      "maxAttempts",
      "concurrency",
      "publicMaxItems",
      "maxItems",
      "playerMaxItems",
    ],
    "debugSummary.agent",
  );
  const agentName = readOptionalString(raw.agent.agentName, "debugSummary.agent.agentName");
  if (agentName && !agents.items[agentName]) {
    throw new Error(`runtime_config_agent_not_found: ${agentName}`);
  }
  return {
    agent: {
      enabled: readOptionalBoolean(raw.agent.enabled, "debugSummary.agent.enabled"),
      agentName,
      timeoutMs: readOptionalPositiveInteger(raw.agent.timeoutMs, "debugSummary.agent.timeoutMs"),
      maxAttempts: readOptionalPositiveInteger(
        raw.agent.maxAttempts,
        "debugSummary.agent.maxAttempts",
      ),
      concurrency: readOptionalPositiveInteger(
        raw.agent.concurrency,
        "debugSummary.agent.concurrency",
      ),
      publicMaxItems: readOptionalMinimumInteger(
        raw.agent.publicMaxItems,
        "debugSummary.agent.publicMaxItems",
        60,
      ),
      maxItems: readOptionalMinimumInteger(raw.agent.maxItems, "debugSummary.agent.maxItems", 50),
      playerMaxItems: readOptionalMinimumInteger(
        raw.agent.playerMaxItems,
        "debugSummary.agent.playerMaxItems",
        60,
      ),
    },
  };
}

export function parseRuntimeConfig(input: {
  providers: unknown;
  agents: unknown;
  game: unknown;
  debugSummary?: unknown;
  environment?: NodeJS.ProcessEnv;
}): RuntimeConfig {
  const environment = input.environment ?? process.env;
  const providers = normalizeProviders(input.providers, environment);
  const agents = normalizeAgents(input.agents, providers);
  const game = normalizeGameConfig(input.game, agents);
  return {
    providers,
    agents,
    game,
    ...(input.debugSummary === undefined
      ? {}
      : { debugSummary: normalizeDebugSummaryConfig(input.debugSummary, agents) }),
  };
}

import { promises as fs } from "node:fs";
import * as path from "node:path";
import type { RuntimeConfig } from "./contracts";
import { parseRuntimeConfig } from "./parse_config";

export interface RuntimeConfigLoadOptions {
  configDir: string;
  gameName: string;
  environment?: NodeJS.ProcessEnv;
}

async function readJsonFile(filePath: string, label: string): Promise<unknown> {
  let raw: string;
  try {
    raw = await fs.readFile(filePath, "utf8");
  } catch (error) {
    const code = (error as NodeJS.ErrnoException).code;
    if (code === "ENOENT") throw new Error(`runtime_config_file_missing: ${label} -> ${filePath}`);
    throw error;
  }
  try {
    return JSON.parse(raw);
  } catch {
    // JSON engine diagnostics can quote values from a providers file.
    throw new Error(`runtime_config_json_invalid: ${label}`);
  }
}

async function readOptionalJsonFile(filePath: string, label: string): Promise<unknown | undefined> {
  try {
    return await readJsonFile(filePath, label);
  } catch (error) {
    if ((error as Error).message.startsWith("runtime_config_file_missing:")) return undefined;
    throw error;
  }
}

export async function loadRuntimeConfig(options: RuntimeConfigLoadOptions): Promise<RuntimeConfig> {
  if (!options.configDir.trim()) throw new Error("runtime_config_missing_configs_dir");
  if (!/^[a-z][a-z0-9_-]*$/.test(options.gameName)) {
    throw new Error(`runtime_config_game_name_invalid: ${options.gameName}`);
  }
  const configRoot = path.resolve(options.configDir);
  const runtimeDir = path.join(configRoot, "runtime");
  return parseRuntimeConfig({
    providers: await readJsonFile(path.join(runtimeDir, "providers.json"), "providers"),
    agents: await readJsonFile(path.join(runtimeDir, "agents.json"), "agents"),
    game: await readJsonFile(
      path.join(configRoot, "games", `${options.gameName}.json`),
      `games.${options.gameName}`,
    ),
    debugSummary: await readOptionalJsonFile(
      path.join(runtimeDir, "debug_summary.json"),
      "debugSummary",
    ),
    environment: options.environment,
  });
}

/**
 * 负责合并已解析配置、运行参数和座位／角色 Agent 选择。输入为公开配置与 CLI 覆盖；
 * 输出为完整对局设置、逐玩家配置和语言回退诊断。仅选择已登记角色，不创建对局、
 * 读取认证或授予行动权限；名字和人格保留原文，不参与模型选择。
 */
import type { BoardConfig } from "../../core";
import type {
  GameConfig,
  GameAgentSelection,
  ResolvedAgentRuntimeProfile,
  ResolvedAuditConfig,
  RuntimeConfig,
  PlayerConfig,
} from "./contracts";
import type { Locale } from "@ai-werewolf-arena/game-contract";
import {
  resolveBoardConfig,
  type BoardName,
  type BoardOverride,
} from "../scenarios/board_config_resolver";
import { type ResolvedBoardDefinition } from "./board_definition";
import { getDefaultRoleCatalog } from "../../game/mechanisms/roles/role-catalog-assembly";
import { Role } from "../../core/domain/identity";

export interface RunGameOptions {
  board: string;
  maxDays: number;
  maxRuntimeMs: number;
  llmTimeoutMs: number;
  trace: boolean;
  printAllEvents: boolean;
  printChat: boolean;
  streamEvents: boolean;
  color: boolean;
  printLlmIo: boolean;
  printThinking: boolean;
  printPrivateEvents: boolean;
  recordRootDir?: string;
}

export interface GameSetupWarning {
  code: "locale_prompt_fallback";
  path: string;
  requestedLocale: Locale;
  fallbackLocale: Locale;
}

export interface ResolvedPlayerConfig {
  name?: string;
  profile?: ResolvedAgentRuntimeProfile;
  personalityPrompt?: string | null;
}

export interface ResolvedGameSetup {
  options: RunGameOptions;
  boardConfig: BoardConfig;
  defaultProfile: ResolvedAgentRuntimeProfile;
  playerProfiles: Readonly<Record<string, ResolvedAgentRuntimeProfile>>;
  roleProfiles: Readonly<Record<string, ResolvedAgentRuntimeProfile>>;
  audit: ResolvedAuditConfig | null;
  boardDefinition?: ResolvedBoardDefinition;
  context: { locale: Locale; displayLocale: Locale; seed?: string };
  players: Readonly<Record<string, ResolvedPlayerConfig>>;
  warnings: readonly GameSetupWarning[];
}

/** 座位／角色分配后才选择 Agent；名字不参与模型选择。 */
export function resolvePlayerProfile(
  setup: ResolvedGameSetup,
  actorId: number,
  role?: Role,
): ResolvedAgentRuntimeProfile {
  const player = setup.players[String(actorId)];
  const selected =
    player?.profile ??
    setup.playerProfiles[String(actorId)] ??
    (role ? setup.roleProfiles[role] : undefined) ??
    setup.defaultProfile;
  return player?.personalityPrompt !== undefined
    ? { ...selected, personalityPrompt: player.personalityPrompt ?? undefined }
    : selected;
}

export function resolveGameBoard(
  runtime: RuntimeConfig,
  overrides: Partial<RunGameOptions> = {},
): string {
  const board = overrides.board ?? runtime.game.board ?? "six_player_mvp";
  if (!/^[a-z][a-z0-9_-]*$/.test(board)) {
    throw new Error(`runtime_config_board_invalid: ${board}`);
  }
  return board;
}

export function resolveAgentProfileByName(
  runtime: RuntimeConfig,
  agentName?: string,
): ResolvedAgentRuntimeProfile {
  const selected = agentName ?? runtime.agents.default;
  const entry = runtime.agents.items[selected];
  if (!entry) throw new Error(`runtime_config_agent_not_found: ${selected}`);
  const provider = runtime.providers.items[entry.provider];
  if (!provider)
    throw new Error(
      `runtime_config_agent_provider_not_found: agent=${selected} provider=${entry.provider}`,
    );
  if (entry.kind === "acp") {
    return {
      name: selected,
      providerName: entry.provider,
      provider,
      kind: "acp",
      spawnArgs: entry.spawnArgs,
      sessionReuse: entry.sessionReuse,
      actionTransport: entry.actionTransport ?? "mcp",
      personalityPrompt: entry.personalityPrompt,
    };
  }
  return {
    name: selected,
    providerName: entry.provider,
    provider,
    kind: "llm",
    model: entry.model,
    temperature: entry.temperature,
    maxTokens: entry.maxTokens,
    reasoningEffort: entry.reasoningEffort,
    thinkingEnabled: entry.thinkingEnabled,
    personalityPrompt: entry.personalityPrompt,
  };
}

function resolveSelections(
  runtime: RuntimeConfig,
  selections: Record<string, GameAgentSelection> | undefined,
): Record<string, ResolvedAgentRuntimeProfile> {
  return Object.fromEntries(
    Object.entries(selections ?? {}).map(([key, selection]) => {
      const name = typeof selection === "string" ? selection : selection.agent;
      const profile = resolveAgentProfileByName(runtime, name);
      const spawnArgs = typeof selection === "object" ? selection.spawnArgs : undefined;
      const personalityPrompt =
        typeof selection === "object" ? selection.personalityPrompt : undefined;
      return [
        key,
        {
          ...profile,
          ...(profile.kind === "acp" && spawnArgs?.length
            ? { spawnArgs: [...(profile.spawnArgs ?? []), ...spawnArgs] }
            : {}),
          ...(personalityPrompt !== undefined ? { personalityPrompt } : {}),
        },
      ];
    }),
  );
}

export function resolveGameSetup(
  runtime: RuntimeConfig,
  overrides: Partial<RunGameOptions> = {},
  boardOverride: BoardOverride | ResolvedBoardDefinition | null = null,
): ResolvedGameSetup {
  if (
    !runtime.providers.items[runtime.providers.default] ||
    !runtime.agents.items[runtime.agents.default]
  ) {
    throw new Error("runtime_config_missing_provider_or_agent_defaults");
  }
  const game = runtime.game;
  const options: RunGameOptions = {
    board: resolveGameBoard(runtime, overrides),
    maxDays: overrides.maxDays ?? game.maxDays ?? 10,
    maxRuntimeMs: overrides.maxRuntimeMs ?? game.maxRuntimeMs ?? 30000,
    llmTimeoutMs: overrides.llmTimeoutMs ?? game.llmTimeoutMs ?? 30000,
    trace: overrides.trace ?? game.trace ?? false,
    printAllEvents: overrides.printAllEvents ?? game.printAllEvents ?? false,
    printChat: overrides.printChat ?? game.printChat ?? false,
    streamEvents: overrides.streamEvents ?? game.streamEvents ?? true,
    color: overrides.color ?? game.color ?? true,
    printLlmIo: overrides.printLlmIo ?? game.printLlmIo ?? false,
    printThinking: overrides.printThinking ?? game.printThinking ?? false,
    printPrivateEvents: overrides.printPrivateEvents ?? game.printPrivateEvents ?? true,
    recordRootDir: overrides.recordRootDir ?? game.recordRootDir,
  };
  const auditConfig = runtime.debugSummary?.agent;
  for (const key of ["maxDays", "maxRuntimeMs", "llmTimeoutMs"] as const) {
    if (!Number.isSafeInteger(options[key]) || options[key] <= 0)
      throw new Error(`runtime_config_positive_integer_invalid: game.${key}`);
  }
  const boardDefinition =
    boardOverride && "definition" in boardOverride ? boardOverride : undefined;
  if (boardDefinition && boardDefinition.definition.id !== options.board)
    throw new Error("runtime_config_board_definition_mismatch");
  if (
    !boardDefinition &&
    options.board !== "six_player_mvp" &&
    options.board !== "twelve_player_standard"
  ) {
    throw new Error(`runtime_config_board_definition_required: ${options.board}`);
  }
  const boardConfig =
    boardDefinition?.config ??
    resolveBoardConfig(options.board as BoardName, boardOverride as BoardOverride | null);
  validateGameBindings(game, boardConfig);
  const locale = game.locale ?? "zh-CN";
  const warnings: GameSetupWarning[] = [];
  const players = resolvePlayers(runtime, game.players, locale, warnings);
  return {
    options,
    boardConfig,
    ...(boardDefinition ? { boardDefinition } : {}),
    context: {
      locale,
      displayLocale: game.displayLocale ?? locale,
      ...(game.seed ? { seed: game.seed } : {}),
    },
    players,
    warnings,
    defaultProfile: resolveAgentProfileByName(runtime, game.agent),
    playerProfiles: resolveSelections(runtime, game.playerAgents),
    roleProfiles: resolveSelections(runtime, game.roleAgents),
    audit:
      auditConfig?.enabled === false
        ? null
        : {
            profile: resolveAgentProfileByName(runtime, auditConfig?.agentName ?? game.agent),
            timeoutMs: auditConfig?.timeoutMs ?? 15000,
            maxAttempts: Math.max(1, auditConfig?.maxAttempts ?? 2),
            concurrency: Math.max(1, auditConfig?.concurrency ?? 4),
            publicMaxItems: Math.max(60, auditConfig?.publicMaxItems ?? 200),
            maxItems: Math.max(50, auditConfig?.maxItems ?? 200),
            playerMaxItems: Math.max(60, auditConfig?.playerMaxItems ?? 120),
          },
  };
}

export function validateGameBindings(game: GameConfig, board: BoardConfig): void {
  const catalog = getDefaultRoleCatalog();
  for (const entry of board.roleSetups) catalog.requireMetadata(entry.role);
  const present = new Set(
    board.roleSetups.filter((entry) => entry.count > 0).map((entry) => entry.role),
  );
  for (const key of Object.keys(game.roleAgents ?? {})) {
    if (!catalog.metadata(key as Role) || !present.has(key as Role))
      throw new Error(`runtime_config_role_binding_invalid: ${key}`);
  }
  for (const key of Object.keys(game.playerAgents ?? {})) {
    if (
      !/^[1-9]\d*$/.test(key) ||
      Number(key) > board.boardSize ||
      !Number.isSafeInteger(Number(key))
    ) {
      throw new Error(`runtime_config_player_binding_invalid: ${key}`);
    }
  }
  for (const key of Object.keys(game.players ?? {})) {
    if (
      !/^[1-9]\d*$/.test(key) ||
      Number(key) > board.boardSize ||
      !Number.isSafeInteger(Number(key))
    )
      throw new Error(`runtime_config_player_binding_invalid: ${key}`);
    if (game.playerAgents && key in game.playerAgents)
      throw new Error(`runtime_config_player_binding_conflict: ${key}`);
  }
}

function resolvePlayers(
  runtime: RuntimeConfig,
  entries: Record<string, PlayerConfig> | undefined,
  locale: Locale,
  warnings: GameSetupWarning[],
): Record<string, ResolvedPlayerConfig> {
  return Object.fromEntries(
    Object.entries(entries ?? {}).map(([seat, entry]) => {
      let profile = entry.agent ? resolveAgentProfileByName(runtime, entry.agent) : undefined;
      if (profile?.kind === "acp" && entry.spawnArgs?.length)
        profile = { ...profile, spawnArgs: [...(profile.spawnArgs ?? []), ...entry.spawnArgs] };
      let personalityPrompt: string | null | undefined =
        entry.personalityPrompt === null ? null : undefined;
      if (typeof entry.personalityPrompt === "string") personalityPrompt = entry.personalityPrompt;
      else if (entry.personalityPrompt) {
        if (entry.personalityPrompt[locale]) personalityPrompt = entry.personalityPrompt[locale];
        else {
          const fallback = entry.personalityPrompt["zh-CN"] ? "zh-CN" : "en";
          personalityPrompt = entry.personalityPrompt[fallback];
          warnings.push({
            code: "locale_prompt_fallback",
            path: `players.${seat}.personalityPrompt`,
            requestedLocale: locale,
            fallbackLocale: fallback,
          });
        }
      }
      return [
        seat,
        {
          ...(entry.name !== undefined ? { name: entry.name } : {}),
          ...(profile ? { profile } : {}),
          ...(personalityPrompt !== undefined ? { personalityPrompt } : {}),
        },
      ];
    }),
  );
}

import { readFile } from "node:fs/promises";
import path from "node:path";
import {
  CONFIG_ID_PATTERN,
  parseBoardDefinition,
  type ResolvedBoardDefinition,
} from "./board_definition";

export async function loadBoardDefinition(
  configDir: string,
  boardId: string,
): Promise<ResolvedBoardDefinition> {
  if (!CONFIG_ID_PATTERN.test(boardId)) throw new Error("board_config_id_invalid");
  const file = path.resolve(configDir, "boards", `${boardId}.json`);
  let text: string;
  try {
    text = await readFile(file, "utf8");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT")
      throw new Error(`board_config_file_missing: ${boardId}`);
    throw error;
  }
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    throw new Error(`board_config_json_invalid: ${boardId}`);
  }
  if (!raw || typeof raw !== "object" || !("version" in raw))
    throw new Error(`board_config_migration_required: ${boardId}`);
  return { ...parseBoardDefinition(raw, boardId), sourceFile: file };
}

/** Explicit conversion of legacy overrides. Normal loading never tries legacy fallbacks. */
import {
  boardDefinitionFromConfig,
  parseBoardDefinition,
  type BoardDefinition,
} from "./board_definition";
import { ActionWindow } from "../../core/domain/model";
import {
  parseBoardOverride,
  resolveBoardConfig,
  type BoardName,
} from "../scenarios/board_config_resolver";

export const MIGRATION_WARNING_CODES = [
  "legacy_defaults_resolved_explicitly",
  "legacy_single_win_condition_shadowed_by_effective_win_conditions",
  "legacy_empty_windows_used_default_pre_vote_window",
  "legacy_windows_with_disabled_hooks_removed_explicitly",
  "legacy_unused_witch_parameters_removed_explicitly",
  "legacy_unsupported_windows_removed_explicitly",
] as const;
export type MigrationWarningCode = (typeof MIGRATION_WARNING_CODES)[number];
export interface BoardMigration {
  definition: BoardDefinition;
  warnings: MigrationWarningCode[];
}

export function convertLegacyBoard(
  raw: unknown,
  boardId: string,
  legacyBase?: BoardName,
): BoardMigration {
  if (raw && typeof raw === "object" && "version" in raw) {
    return { definition: parseBoardDefinition(raw, boardId).definition, warnings: [] };
  }
  const base = legacyBase ?? boardId;
  if (base !== "six_player_mvp" && base !== "twelve_player_standard") {
    throw new Error("board_config_legacy_base_unknown");
  }
  const override = parseBoardOverride(raw, (legacyBase ?? boardId) as BoardName);
  if (!override) throw new Error("board_config_legacy_shape_invalid");
  const historical = { ...override };
  // Unversioned files retain their historical execution semantics during conversion.
  if (historical.selfDestruct?.enabledWindows.length === 0) delete historical.selfDestruct;
  const effective = resolveBoardConfig(base as BoardName, historical);
  const unsupported =
    effective.selfDestruct?.enabledWindows.filter((window) => window !== ActionWindow.OnPreVote) ??
    [];
  if (unsupported.length)
    effective.selfDestruct = {
      enabledWindows: effective.selfDestruct!.enabledWindows.filter(
        (window) => window === ActionWindow.OnPreVote,
      ),
    };
  const warnings: MigrationWarningCode[] = ["legacy_defaults_resolved_explicitly"];
  if (unsupported.length) warnings.push("legacy_unsupported_windows_removed_explicitly");
  if (override.winCondition && effective.winConditions?.length)
    warnings.push("legacy_single_win_condition_shadowed_by_effective_win_conditions");
  if (override.selfDestruct?.enabledWindows.length === 0 && effective.hooks.onPreVote)
    warnings.push("legacy_empty_windows_used_default_pre_vote_window");
  const windowHooks = {
    [ActionWindow.OnPreVote]: effective.hooks.onPreVote,
    [ActionWindow.OnDaybreak]: effective.hooks.onDaybreak,
    [ActionWindow.OnPreElection]: effective.hooks.onPreElection,
    [ActionWindow.OnPerSpeechGap]: effective.hooks.onPerSpeechGap,
  };
  if (
    [...unsupported, ...(effective.selfDestruct?.enabledWindows ?? [])].some(
      (window) => !windowHooks[window],
    )
  )
    warnings.push("legacy_windows_with_disabled_hooks_removed_explicitly");
  if (
    override.witch &&
    !effective.roleSetups.some((entry) => entry.role === "witch" && entry.count > 0)
  )
    warnings.push("legacy_unused_witch_parameters_removed_explicitly");
  return { definition: boardDefinitionFromConfig(boardId, effective), warnings };
}

